:root {
  --ink: #2b1d0e;
  --parchment: #f2e8d5;
  --aged: #d9c9a8;
  --rust: #a0442a;
  --gold: #b8892e;
  --gold-light: #e4c87a;
  --deep-blue: #1e3a5f;
  --cobalt: #2e5fa3;
  --ruby: #8b1c2e;
  --emerald: #1a6644;
  --amber: #c97820;
  --violet: #5c2d7a;
  --cream: #faf4e8;
  --border: #8b6a3e;
  --muted: #6b543a;
  --urgent-bg: #fdf0ec;
  --urgent-border: #a0442a;
}

.log-card {
  background: var(--parchment);
  border: 2px solid var(--border);
  border-radius: 4px;
  width: 480px;
  font-size: 13px;
  color: var(--ink);
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
}

.log-header {
  background: var(--deep-blue);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 3px solid var(--gold);
}

.studio-badge {
  background: var(--gold);
  color: var(--deep-blue);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  padding: 4px 7px;
  border-radius: 2px;
}

.header-center {
  text-align: center;
}

.studio-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--gold-light);
  margin: 0;
  letter-spacing: 1px;
  line-height: 1.1;
}

.studio-sub {
  font-size: 10px;
  color: var(--aged);
  margin: 2px 0 0;
  letter-spacing: 0.5px;
}

.log-number {
  text-align: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.log-label {
  font-size: 9px;
  color: var(--aged);
  letter-spacing: 2px;
}

.log-id {
  font-size: 13px;
  font-weight: 700;
  color: var(--gold-light);
}

.log-body {
  display: flex;
  flex-direction: row;
  gap: 0;
}

.piece-info {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
  border-right: 1px solid var(--aged);
  width: 200px;
  flex-shrink: 0;
}

.piece-preview {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.mosaic-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
  background: var(--ink);
  padding: 3px;
  border-radius: 3px;
  width: 72px;
  height: 72px;
}

.tile {
  border-radius: 1px;
}

.t1 { background: var(--cobalt); }
.t2 { background: var(--ruby); }
.t3 { background: var(--gold); }
.t4 { background: var(--emerald); }
.t5 { background: var(--amber); }
.t6 { background: var(--violet); }
.t7 { background: var(--gold); }
.t8 { background: var(--cobalt); }
.t9 { background: var(--ruby); }

.piece-caption {
  font-size: 10px;
  color: var(--muted);
  margin: 0;
  text-align: center;
  font-style: italic;
}

.piece-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px;
  border-bottom: 1px dotted var(--aged);
  padding-bottom: 3px;
}

.detail-label {
  font-size: 10px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}

.detail-value {
  font-size: 11px;
  color: var(--ink);
  font-weight: 500;
  text-align: right;
}

.condition-section {
  flex: 1;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin: 0 0 2px;
  border-bottom: 1px solid var(--aged);
  padding-bottom: 4px;
}

.condition-bars {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  font-size: 11px;
  color: var(--ink);
  width: 90px;
  flex-shrink: 0;
}

.bar-track {
  flex: 1;
  height: 10px;
  background: var(--aged);
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid var(--border);
}

.bar-fill {
  height: 100%;
  border-radius: 5px;
}

.bar-fill.lead {
  width: 62%;
  background: var(--cobalt);
}

.bar-fill.clarity {
  width: 85%;
  background: var(--emerald);
}

.bar-fill.grout {
  width: 41%;
  background: var(--rust);
}

.bar-pct {
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  width: 30px;
  text-align: right;
}

.log-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-top: 2px solid var(--border);
  background: var(--cream);
}

.status-tag {
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 3px;
  letter-spacing: 0.5px;
}

.status-tag.urgent {
  background: var(--urgent-bg);
  color: var(--rust);
  border: 1px solid var(--urgent-border);
}

.footer-note {
  font-size: 11px;
  color: var(--muted);
  font-style: italic;
}

.studio-seal {
  font-size: 10px;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 1px;
}
